class Solution {
    public int findMin(int[] nums) {
        int low = 0, high = nums.length - 1;
        while (low <= high) {
            int mid = low + (high - low) / 2;
            if (nums[low] <= nums[mid]) {
                if (mid + 1 <= high && nums[mid + 1] <= nums[high]) {
                    return Math.min(nums[low], nums[mid + 1]);
                } else {
                    low = mid + 1;
                }
            } else {
                high = mid;
            }
        }
        return nums[high];
    }
}

solutions.trapping-rain-water:java:
class Solution {
    public int trap(int[] height) {
        int n = height.length;
        int[] rMax = new int[n];
        int max = height[n - 1];
        rMax[n - 1] = max;
        for (int i = n - 2; i >= 0; i--) {
            max = Math.max(max, height[i]);
            rMax[i] = max;
        }
        max = height[0];
        int vol = 0;
        for (int i = 1; i < n; i++) {
            max = Math.max(max, height[i]);
            vol += Math.max(0, Math.min(max, rMax[i]) - height[i]);
        }
        return vol;
    }
}

solutions.diameter-of-binary-tree:java:
/*
Definition for a binary tree node.
class TreeNode {
    int val;
    TreeNode left;
    TreeNode right;
    TreeNode() {}
    TreeNode(int val) { this.val = val; }
    TreeNode(int val, TreeNode left, TreeNode right) { this.val = val; this.left = left; this.right = right; }
}
*/
class Solution {
    private static int[] none = new int[] { 0, 0 };

    public int diameterOfBinaryTree(TreeNode root) {
        return helper(root)[1];
    }

    private int[] helper(TreeNode root) {
        if (root == null) {
            return none;
        }
        if (root.left == null && root.right == null) {
            return none;
        }
        int[] left = helper(root.left);
        int[] right = helper(root.right);
        int d = left[0] + right[0];
        if (root.left != null) {
            d++;
        }
        if (root.right != null) {
            d++;
        }
        int h = 1 + Math.max(left[0], right[0]);
        d = Math.max(d, Math.max(left[1], right[1]));
        return new int[] { h, d };
    }
}

solutions.palindromic-substrings:java:
class Solution {
    public int countSubstrings(String s) {
        int len = 0;
        for (int i = 0; i < s.length(); i++) {
            len += countPalindromes(s, i, i);
            len += countPalindromes(s, i, i + 1);
        }
        return len;
    }

    private int countPalindromes(String s, int i, int j) {
        int count = 0;
        while (i >= 0 && j < s.length() && s.charAt(i) == s.charAt(j)) {
            count++;
            i--;
            j++;
        }
        return count;
    }
}

solutions.reorder-list:java:
/*
Definition for singly-linked list. 
ListNode {
    int val;
    ListNode next;
    ListNode() {}
    ListNode(int val) { this.val = val; }
    ListNode(int val, ListNode next) { this.val = val; this.next = next; }
}
*/
class Solution {
    public ListNode reorderList(ListNode head) {
        if (head == null) {
            return null;
        }
        ListNode sent = new ListNode(0, head);
        ListNode slow = sent, fast = sent;
        while (fast != null && fast.next != null) {
            slow = slow.next;
            fast = fast.next.next;
        }
        ListNode head2 = slow.next;
        slow.next = null;

        ListNode prev = null, curr = head2;
        while (curr != null) {
            ListNode fut = curr.next;
            curr.next = prev;
            prev = curr;
            curr = fut;
        }
        head2 = prev;
        ListNode ptr = sent;
        while (head != null && head2 != null) {
            ptr.next = head;
            head = head.next;
            ptr = ptr.next;
            ptr.next = head2;
            head2 = head2.next;
            ptr = ptr.next;
        }
        ptr.next = head == null ? head2 : head;
        return sent.next;
    }
}

solutions.top-k-frequent-elements:java:
import java.util.*;

class Solution {
    public int[] topKFrequent(int[] nums, int k) {
        Map<Integer, Integer> map = new HashMap<>();
        for (int num : nums) {
            map.put(num, map.getOrDefault(num, 0) + 1);
        }
        int n = nums.length;
        List<List<Integer>> freq = new ArrayList<>(n);
        for (int i = 0; i < n; i++) {
            freq.add(new ArrayList<>());
        }
        for (var entry : map.entrySet()) {
            freq.get(entry.getValue() - 1).add(entry.getKey());
        }
        int[] result = new int[k];
        for (int i = n - 1; i >= 0; i--) {
            int j = 0;
            while (k > 0 && j < freq.get(i).size()) {
                result[k - 1] = freq.get(i).get(j);
                k--;
                j++;
            }
            if (k == 0)
                break;
        }
        return result;
    }
}

solutions.encode-and-decode-strings:java:
import java.util.*;

public class Codec {
    // Encodes a list of strings to a single string.
    public String encode(String[] strs) {
        StringBuilder result = new StringBuilder();
        for (String str : strs) {
            result.append(str.length()).append('#').append(str);
        }
        return result.toString();
    }

    // Decodes a single string to a list of strings.
    public List<String> decode(String s) {
        List<String> result = new ArrayList<>();
        int i = 0;
        int n = 0;
        while (i < s.length()) {
            char ch = s.charAt(i);
            if (Character.isDigit(ch)) {
                n = 0;
                while (Character.isDigit(s.charAt(i))) {
                    n = 10 * n + s.charAt(i) - '0';
                    i++;
                }
                result.add(s.substring(i + 1, i + 1 + n));
                i = i + 1 + n;
            }
        }
        return result;
    }
}

solutions.spiral-matrix:java:
class Solution {
    public int[] spiralOrder(int[][] matrix) {
        int left, right, top, bottom;
        left = top = 0;
        bottom = matrix.length;
        right = matrix[0].length;
        int[] result = new int[bottom * right];
        int i, j, k;
        i = j = k = 0;
        while (k < result.length) {
            while (j < right) {
                result[k++] = matrix[i][j++];
            }
            if (k == result.length) {
                break;
            }
            j--;
            i++;
            top++;
            while (i < bottom) {
                result[k++] = matrix[i++][j];
            }
            if (k == result.length) {
                break;
            }
            i--;
            j--;
            right--;
            while (j >= left) {
                result[k++] = matrix[i][j--];
            }
            if (k == result.length) {
                break;
            }
            j++;
            i--;
            bottom--;
            while (i >= top) {
                result[k++] = matrix[i--][j];
            }
            i++;
            j++;
            left++;
        }
        return result;
    }
}

solutions.balanced-binary-tree:java:
/*
Definition for a binary tree node.
class TreeNode {
    int val;
    TreeNode left;
    TreeNode right;
    TreeNode() {}
    TreeNode(int val) { this.val = val; }
    TreeNode(int val, TreeNode left, TreeNode right) { this.val = val; this.left = left; this.right = right; }
}
*/
class Solution {
    private record Pair(boolean isBalanced, int h) {
        static Pair EMPTY = new Pair(true, 0);
    };

    public boolean isBalanced(TreeNode root) {
        return helper(root).isBalanced;
    }

    private Pair helper(TreeNode root) {
        if (root == null) {
            return Pair.EMPTY;
        }
        Pair left = helper(root.left);
        Pair right = helper(root.right);
        boolean isBalanced = left.isBalanced &&
                right.isBalanced &&
                (Math.abs(left.h - right.h) <= 1);
        int h = 1 + Math.max(left.h, right.h);
        return new Pair(isBalanced, h);
    }
}

solutions.gas-station:java:
class Solution {
    public int canCompleteCircuit(int[] gas, int[] cost) {
        int globalBalance = 0, localBalance = 0, startIndex = 0;
        for (int i = 0; i < gas.length; i++) {
            int currentBalance = gas[i] - cost[i];
            globalBalance += currentBalance;
            localBalance += currentBalance;
            if (localBalance < 0) {
                localBalance = 0;
                startIndex = i + 1;
            }
        }
        return globalBalance < 0 ? -1 : startIndex % gas.length;
    }
}

