import java.util.*;

class Solution {
    public int eraseOverlapIntervals(int[][] intervals) {
        Arrays.sort(intervals, (a, b) -> a[0] - b[0]);
        int count = 0;
        int end = intervals[0][1];
        for (int i = 1; i < intervals.length; i++) {
            if (end <= intervals[i][0]) {
                end = intervals[i][1];
            } else {
                end = Math.min(end, intervals[i][1]);
                count++;
            }
        }
        return count;
    }
}

solutions.longest-palindromic-substring:java:
class Solution {
    public String longestPalindrome(String s) {
        int startIndex = 0, maxLen = 1;
        int n = s.length();
        boolean[][] dp = new boolean[n][n];
        for (int i = n - 1; i >= 0; i--) {
            dp[i][i] = true;
            for (int j = i + 1; j < n; j++) {
                int len = j - i + 1;
                dp[i][j] = s.charAt(i) == s.charAt(j) && (len == 2 ? true : dp[i + 1][j - 1]);
                if (dp[i][j] && len > maxLen) {
                    startIndex = i;
                    maxLen = len;
                }
            }
        }
        return s.substring(startIndex, startIndex + maxLen);
    }
}

solutions.house-robber-iii:java:
/*
Definition for a binary tree node.
class TreeNode {
    int val;
    TreeNode left;
    TreeNode right;
    TreeNode() {}
    TreeNode(int val) { this.val = val; }
    TreeNode(int val, TreeNode left, TreeNode right) { this.val = val; this.left = left; this.right = right; }
}
*/

class Solution {
    private record Pair(int max, int childMax) {
        static final Pair EMPTY = new Pair(0, 0);
    }

    public int rob(TreeNode root) {
        var pair = robHelper(root);
        return pair.max;
    }

    private Pair robHelper(TreeNode root) {
        if (root == null) {
            return Pair.EMPTY;
        }
        var leftPair = robHelper(root.left);
        var rightPair = robHelper(root.right);

        int childMax = leftPair.max + rightPair.max;
        int max = Math.max(childMax, root.val + leftPair.childMax + rightPair.childMax);
        return new Pair(max, childMax);
    }
}

solutions.max-area-of-island:java:
class Solution {
    public int maxAreaOfIsland(int[][] grid) {
        int m = grid.length;
        int n = grid[0].length;
        int maxArea = 0;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1) {
                    maxArea = Math.max(maxArea, area(grid, i, j, m, n));
                }
            }
        }
        return maxArea;
    }

    private int area(int[][] grid, int i, int j, int m, int n) {
        if (i < 0 || j < 0 || i >= m || j >= n || grid[i][j] != 1) {
            return 0;
        }
        grid[i][j] = 2;
        return 1 + area(grid, i + 1, j, m, n) + area(grid, i - 1, j, m, n) + area(grid, i, j + 1, m, n)
                + area(grid, i, j - 1, m, n);
    }
}

solutions.number-of-islands:java:
import java.util.*;

class Solution {
    public int numIslands(int[][] grid) {
        int m = grid.length;
        int n = grid[0].length;
        int count = 0;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1) {
                    dfs(grid, i, j, m, n);
                    count++;
                }
            }
        }
        return count;
    }

    private void dfs(int[][] grid, int i, int j, int m, int n) {
        if (i < 0 || j < 0 || i >= m || j >= n || grid[i][j] != 1) {
            return;
        }
        grid[i][j] = 2;
        dfs(grid, i + 1, j, m, n);
        dfs(grid, i - 1, j, m, n);
        dfs(grid, i, j + 1, m, n);
        dfs(grid, i, j - 1, m, n);
    }
}

solutions.permutations:java:
import java.util.*;

class Solution {

    public int[][] permute(int[] nums) {
        List<int[]> results = new ArrayList<>();
        permute(nums, 0, results);
        return results.toArray(new int[0][]);
    }

    private void permute(int[] nums, int start, List<int[]> results) {
        if (start == nums.length) {
            int[] arr = new int[nums.length];
            System.arraycopy(nums, 0, arr, 0, nums.length);
            results.add(arr);
            return;
        }
        for (int i = start; i < nums.length; i++) {
            swap(nums, i, start);
            permute(nums, start + 1, results);
            swap(nums, i, start);
        }
    }

    private void swap(int[] nums, int i, int j) {
        int temp = nums[i];
        nums[i] = nums[j];
        nums[j] = temp;
    }
}

solutions.letter-combinations-of-a-phone-number:ja:
import java.util.*;

class Solution {
    public List<String> letterCombinations(String digits) {
        Map<Character, List<Character>> map = new HashMap<>();
        char chVal = 'a';
        for (int i = 2; i <= 9; i++) {
            char chKey = (char) (i + '0');
            int limit = i == 7 || i == 9 ? 4 : 3;
            for (int j = 0; j < limit; j++) {
                map.computeIfAbsent(chKey, k -> new ArrayList<>()).add(chVal);
                chVal++;
            }
        }
        StringBuilder sb = new StringBuilder();
        List<String> result = new ArrayList<>();
        helper(digits, 0, map, sb, result);
        return result;
    }

    private void helper(String digits, int index, Map<Character, List<Character>> map, StringBuilder sb,
            List<String> result) {
        if (index == digits.length()) {
            result.add(sb.toString());
            return;
        }
        for (char ch : map.get(digits.charAt(index))) {
            sb.append(ch);
            helper(digits, index + 1, map, sb, result);
            sb.deleteCharAt(sb.length() - 1);
        }
    }
}

solutions.last-stone-weight:java:
import java.util.*;

class Solution {
    public int lastStoneWeight(int[] stones) {
        Queue<Integer> pq = new PriorityQueue<>((a, b) -> b - a);
        for (int stone : stones) {
            pq.add(stone);
        }
        while (!pq.isEmpty()) {
            int h = pq.poll();
            if (pq.isEmpty()) {
                return h;
            }
            int l = pq.poll();
            if (h != l) {
                pq.offer(h - l);
            }
        }
        return 0;
    }
}

solutions.word-search-ii:java:
import java.util.*;

class Solution {
    private class TrieNode {
        TrieNode[] children;

        public TrieNode() {
            children = new TrieNode[26];
        }
    };

    private TrieNode head;

    public List<String> findWords(char[][] board, String[] words) {
        head = new TrieNode();
        Arrays.sort(words, (s1, s2) -> {
            int len = Math.min(s1.length(), s2.length());
            for (int i = 0; i < len; i++) {
                if (s1.charAt(i) != s2.charAt(i)) {
                    return s1.charAt(i) - s2.charAt(i);
                }
            }
            return s1.length() > s2.length() ? s2.length() - s1.length() : s1.length() - s2.length();
        });
        List<String> result = new ArrayList<>();
        for (String word : words) {
            if (found(word)) {
                result.add(word);
            } else if (found(board, word)) {
                add(word);
                result.add(word);
            }
        }
        return result;
    }

    private void add(String word) {
        TrieNode ptr = head;
        for (int i = 0; i < word.length(); i++) {
            if (ptr.children[word.charAt(i) - 'a'] == null) {
                ptr.children[word.charAt(i) - 'a'] = new TrieNode();
            }
            ptr = ptr.children[word.charAt(i) - 'a'];
        }
    }

    private boolean found(String word) {
        TrieNode ptr = head;
        for (int i = 0; i < word.length(); i++) {
            if (ptr.children[word.charAt(i) - 'a'] == null) {
                return false;
            }
            ptr = ptr.children[word.charAt(i) - 'a'];
        }
        return true;
    }

    private boolean found(char[][] board, String word) {
        int m = board.length;
        int n = board[0].length;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (word.charAt(0) == board[i][j] && found(board, word, i, j, m, n, 0)) {
                    return true;
                }
            }
        }
        return false;
    }

    private boolean found(char[][] board, String word, int i, int j, int m, int n, int index) {
        if (index == word.length()) {
            return true;
        }
        if (i < 0 || j < 0 || i >= m || j >= n || board[i][j] != word.charAt(index)) {
            return false;
        }
        char ch = board[i][j];
        board[i][j] = '#';
        boolean exists = found(board, word, i + 1, j, m, n, index + 1) || found(board, word, i - 1, j, m, n, index + 1)
                || found(board, word, i, j - 1, m, n, index + 1) || found(board, word, i, j + 1, m, n, index + 1);
        board[i][j] = ch;
        return exists;
    }
}

solutions.subtree-of-another-tree:java:
import java.util.*;

/*
Definition for a binary tree node.
class TreeNode {
    int val;
    TreeNode left;
    TreeNode right;
    TreeNode() {}
    TreeNode(int val) { this.val = val; }
    TreeNode(int val, TreeNode left, TreeNode right) { this.val = val; this.left = left; this.right = right; }
}
*/
class Solution {
    public boolean isSubtree(TreeNode root, TreeNode subRoot) {
        StringBuilder sb1 = new StringBuilder();
        StringBuilder sb2 = new StringBuilder();
        helper(root, sb1);
        helper(subRoot, sb2);
        return sb1.indexOf(sb2.toString()) > -1;
    }

    private void helper(TreeNode root, StringBuilder sb) {
        if (root == null) {
            sb.append("N,");
            return;
        }
        sb.append('#');
        sb.append(root.val);
        sb.append(',');
        helper(root.left, sb);
        helper(root.right, sb);
    }
}

