import java.util.*;

/*
Definition for a binary tree node.
class TreeNode {
    int val;
    TreeNode left;
    TreeNode right;
    TreeNode() {}
    TreeNode(int val) { this.val = val; }
    TreeNode(int val, TreeNode left, TreeNode right) { this.val = val; this.left = left; this.right = right; }
}
*/
class Solution {
    public int maxDepth(TreeNode root) {
        if (root == null)
            return 0;
        if (root.left == null && root.right == null)
            return 1;
        int left = maxDepth(root.left);
        int right = maxDepth(root.right);
        return 1 + Math.max(left, right);
    }
}

solutions.koko-eating-bananas:java:
import java.util.*;

class Solution {
    public int minEatingSpeed(int[] piles, int h) {
        int low = 1, high = piles[0];
        for (int i = 1; i < piles.length; i++) {
            if (high < piles[i]) {
                high = piles[i];
            }
        }
        while (low <= high) {
            int mid = low + (high - low) / 2;
            int actualHours = 0;
            for (int pile : piles) {
                actualHours += Math.ceil((pile * 1.0) / mid);
            }
            if (actualHours > h) {
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }
        return low;
    }
}

solutions.sliding-window-maximum:java:
import java.util.*;

class Solution {
    public int[] maxSlidingWindow(int[] nums, int k) {
        Deque<Integer> dq = new ArrayDeque<>();
        int[] result = new int[nums.length - k + 1];
        int i = 0, j = 0, r = 0;
        while (j < nums.length) {
            if (j - i + 1 > k) {
                if (!dq.isEmpty() && dq.peekFirst() == i) {
                    dq.pollFirst();
                }
                i++;
            }
            while (!dq.isEmpty() && nums[dq.peekLast()] <= nums[j]) {
                dq.pollLast();
            }
            dq.offerLast(j);
            if (j - i + 1 == k) {
                result[r++] = nums[dq.peekFirst()];
            }
            j++;
        }
        return result;
    }
}

solutions.generate-parentheses:java:
import java.util.*;

class Solution {
    public List<String> generateParenthesis(int n) {
        List<String> result = new ArrayList<>();
        StringBuilder sb = new StringBuilder();
        generateParenthesis(n, n, sb, result);
        return result;
    }

    private void generateParenthesis(int left, int right, StringBuilder sb, List<String> result) {
        if (left == 0 && right == 0) {
            result.add(sb.toString());
            return;
        }
        if (left > 0) {
            sb.append('(');
            generateParenthesis(left - 1, right, sb, result);
            sb.deleteCharAt(sb.length() - 1);
        }
        if (right > left) {
            sb.append(')');
            generateParenthesis(left, right - 1, sb, result);
            sb.deleteCharAt(sb.length() - 1);
        }
    }
}

