import java.util.*;

class Solution {
    public int orangesRotting(int[][] grid) {
        int[][] dir = new int[][] {{0, -1}, {0, 1}, {1, 0}, {-1, 0}};
        Deque<int[]> q = new ArrayDeque<>();
        int freshCount = 0;
        int m = grid.length;
        int n = grid[0].length;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1) {
                    freshCount++;
                } else if (grid[i][j] == 2) {
                    q.offer(new int[] {i, j});
                }
            }
        }
        int minutes = 0;
        while (!q.isEmpty() && freshCount > 0) {
            int size = q.size();
            minutes++;
            for (int i = 0; i < size; i++) {
                int[] point = q.poll();
                for (int j = 0; j < 4; j++) {
                    int x = point[0] + dir[j][0];
                    int y = point[1] + dir[j][1];
                    if (x < 0 || x >= m || y < 0 || y >= n) {
                        continue;
                    }
                    if (grid[x][y] == 1) {
                        grid[x][y] = 2;
                        freshCount--;
                        q.offer(new int[] {x, y});
                    }
                }
            }
        }
        return freshCount > 0 ? -1 : minutes;
    }
}

solutions.redundant-connection:java:
import java.util.*;

class Solution {
    private class DisjointSet {
        private int n;
        private int[] size;
        private int[] parent;


        public DisjointSet(int n) {
            this.n = n;
            size = new int[n + 1];
            Arrays.fill(size, 1);
            parent = new int[n + 1];
            for (int i = 0; i <= n; i++) {
                parent[i] = i;
            }
        }

        public boolean isConnected(int n1, int n2) {
            return findUltimateParent(n1) == findUltimateParent(n2);
        }

        private int findUltimateParent(int node) {
            if (parent[node] == node)
                return node;
            return parent[node] = findUltimateParent(parent[node]);
        }

        public void unionBySize(int n1, int n2) {
            if (isConnected(n1, n2)) {
                return;
            }
            int up1 = findUltimateParent(n1);
            int up2 = findUltimateParent(n2);
            if (size[up1] > size[up2]) {
                size[up1] += size[up2];
                parent[up2] = up1;
            } else {
                size[up2] += size[up1];
                parent[up1] = up2;
            }
        }
    };

    public int[] findRedundantConnection(int[][] edges) {
        DisjointSet ds = new DisjointSet(edges.length);
        for (int[] edge : edges) {
            if (ds.isConnected(edge[0], edge[1])) {
                return edge;
            }
            ds.unionBySize(edge[0], edge[1]);
        }
        return new int[0];
    }
}

solutions.course-schedule-ii:java:
import java.util.*;

class Solution {
    public int[] findOrder(int numCourses, int[][] prerequisites) {
        List<List<Integer>> adj = new ArrayList<>(numCourses);
        for (int i = 0; i < numCourses; i++) {
            adj.add(new ArrayList<>());
        }
        for (int[] pre : prerequisites) {
            adj.get(pre[1]).add(pre[0]);
        }
        Deque<Integer> dq = new ArrayDeque<>();
        byte[] visited = new byte[numCourses];
        // 0 - unvisited, 1 - visiting, 2 - visited
        for (int i = 0; i < numCourses; i++) {
            if (visited[i] == 0 && hasCycle(i, dq, visited, adj)) {
                return new int[0];
            }
        }
        int[] result = new int[numCourses];
        for (int i = 0; i < numCourses; i++) {
            result[i] = dq.pop();
        }
        return result;
    }

    private boolean hasCycle(int node, Deque<Integer> dq, byte[] visited, List<List<Integer>> adj) {
        // 0 - unvisited, 1 - visiting, 2 - visited
        visited[node] = 1;
        for (int nei : adj.get(node)) {
            if (visited[nei] == 1) {
                return true;
            }
            if (visited[nei] == 0 && hasCycle(nei, dq, visited, adj)) {
                return true;
            }
        }
        dq.push(node);
        visited[node] = 2;
        return false;
    }
}

