class Solution {
    public int trap(int[] height) {
        int n = height.length;
        int[] rMax = new int[n];
        int max = height[n - 1];
        rMax[n - 1] = max;
        for (int i = n - 2; i >= 0; i--) {
            max = Math.max(max, height[i]);
            rMax[i] = max;
        }
        max = height[0];
        int vol = 0;
        for (int i = 1; i < n; i++) {
            max = Math.max(max, height[i]);
            vol += Math.max(0, Math.min(max, rMax[i]) - height[i]);
        }
        return vol;
    }
}

diameter-of-binary-tree.code:
/*
Definition for a binary tree node.
class TreeNode {
    int val;
    TreeNode left;
    TreeNode right;
    TreeNode() {}
    TreeNode(int val) { this.val = val; }
    TreeNode(int val, TreeNode left, TreeNode right) { this.val = val; this.left = left; this.right = right; }
}
*/
class Solution {
    private static int[] none = new int[] { 0, 0 };

    public int diameterOfBinaryTree(TreeNode root) {
        return helper(root)[1];
    }

    private int[] helper(TreeNode root) {
        if (root == null) {
            return none;
        }
        if (root.left == null && root.right == null) {
            return none;
        }
        int[] left = helper(root.left);
        int[] right = helper(root.right);
        int d = left[0] + right[0];
        if (root.left != null) {
            d++;
        }
        if (root.right != null) {
            d++;
        }
        int h = 1 + Math.max(left[0], right[0]);
        d = Math.max(d, Math.max(left[1], right[1]));
        return new int[] { h, d };
    }
}

palindromic-substrings.code:
class Solution {
    public int countSubstrings(String s) {
        int n = s.length();
        boolean[][] dp = new boolean[n][n];
        int count = n;
        for (int i = n - 1; i >= 0; i--) {
            dp[i][i] = true;
            for (int j = i + 1; j < n; j++) {
                int len = j - i + 1;
                if (len == 2) {
                    dp[i][j] = s.charAt(i) == s.charAt(j);
                } else {
                    dp[i][j] = dp[i + 1][j - 1] && s.charAt(i) == s.charAt(j);
                }
                if (dp[i][j]) {
                    count++;
                }
            }
        }
        return count;
    }
}

class Solution {
    public int countSubstrings(String s) {
        int len = 0;
        for (int i = 0; i < s.length(); i++) {
            len += countPalindromes(s, i, i);
            len += countPalindromes(s, i, i + 1);
        }
        return len;
    }

    private int countPalindromes(String s, int i, int j) {
        int count = 0;
        while (i >= 0 && j < s.length() && s.charAt(i) == s.charAt(j)) {
            count++;
            i--;
            j++;
        }
        return count;
    }
}

reorder-list.code:
/*
Definition for singly-linked list. 
ListNode {
    int val;
    ListNode next;
    ListNode() {}
    ListNode(int val) { this.val = val; }
    ListNode(int val, ListNode next) { this.val = val; this.next = next; }
}
*/
class Solution {
    public ListNode reorderList(ListNode head) {
        if (head == null) {
            return null;
        }
        ListNode sent = new ListNode(0, head);
        ListNode slow = sent, fast = sent;
        while (fast != null && fast.next != null) {
            slow = slow.next;
            fast = fast.next.next;
        }
        ListNode head2 = slow.next;
        slow.next = null;

        ListNode prev = null, curr = head2;
        while (curr != null) {
            ListNode fut = curr.next;
            curr.next = prev;
            prev = curr;
            curr = fut;
        }
        head2 = prev;
        ListNode ptr = sent;
        while (head != null && head2 != null) {
            ptr.next = head;
            head = head.next;
            ptr = ptr.next;
            ptr.next = head2;
            head2 = head2.next;
            ptr = ptr.next;
        }
        ptr.next = head == null ? head2 : head;
        return sent.next;
    }
}

top-k-frequent-elements.code:
import java.util.*;

class Solution {
    public int[] topKFrequent(int[] nums, int k) {
        Map<Integer, Integer> map = new HashMap<>();
        for (int num : nums) {
            map.put(num, map.getOrDefault(num, 0) + 1);
        }
        Queue<int[]> q = new PriorityQueue<>((a, b) -> a[1] - b[1]);
        for (var entry : map.entrySet()) {
            int[] arr = new int[] { entry.getKey(), entry.getValue() };
            if (q.size() < k) {
                q.offer(arr);
            } else if (q.peek()[1] < arr[1]) {
                q.poll();
                q.offer(arr);
            }
        }
        int[] result = new int[k];
        for (int i = 0; i < k; i++) {
            result[i] = q.poll()[0];
        }
        return result;
    }
}

import java.util.*;

class Solution {
    public int[] topKFrequent(int[] nums, int k) {
        Map<Integer, Integer> map = new HashMap<>();
        for (int num : nums) {
            map.put(num, map.getOrDefault(num, 0) + 1);
        }
        int n = nums.length;
        List<List<Integer>> freq = new ArrayList<>(n);
        for (int i = 0; i < n; i++) {
            freq.add(new ArrayList<>());
        }
        for (var entry : map.entrySet()) {
            freq.get(entry.getValue() - 1).add(entry.getKey());
        }
        int[] result = new int[k];
        for (int i = n - 1; i >= 0; i--) {
            int j = 0;
            while (k > 0 && j < freq.get(i).size()) {
                result[k - 1] = freq.get(i).get(j);
                k--;
                j++;
            }
            if (k == 0)
                break;
        }
        return result;
    }
}

