import java.util.*;

public class Codec {
    // Encodes a list of strings to a single string.
    public String encode(String[] strs) {
        StringBuilder result = new StringBuilder();
        for (String str : strs) {
            result.append(str.length()).append('#').append(str);
        }
        return result.toString();
    }

    // Decodes a single string to a list of strings.
    public List<String> decode(String s) {
        List<String> result = new ArrayList<>();
        int i = 0;
        int n = 0;
        while (i < s.length()) {
            char ch = s.charAt(i);
            if (Character.isDigit(ch)) {
                n = 0;
                while (Character.isDigit(s.charAt(i))) {
                    n = 10 * n + s.charAt(i) - '0';
                    i++;
                }
                result.add(s.substring(i + 1, i + 1 + n));
                i = i + 1 + n;
            }
        }
        return result;
    }
}

spiral-matrix.code:
class Solution {
    public int[] spiralOrder(int[][] matrix) {
        int left, right, top, bottom;
        left = top = 0;
        bottom = matrix.length;
        right = matrix[0].length;
        int[] result = new int[bottom * right];
        int i, j, k;
        i = j = k = 0;
        while (k < result.length) {
            while (j < right) {
                result[k++] = matrix[i][j++];
            }
            if (k == result.length) {
                break;
            }
            j--;
            i++;
            top++;
            while (i < bottom) {
                result[k++] = matrix[i++][j];
            }
            if (k == result.length) {
                break;
            }
            i--;
            j--;
            right--;
            while (j >= left) {
                result[k++] = matrix[i][j--];
            }
            if (k == result.length) {
                break;
            }
            j++;
            i--;
            bottom--;
            while (i >= top) {
                result[k++] = matrix[i--][j];
            }
            i++;
            j++;
            left++;
        }
        return result;
    }
}

balanced-binary-tree.code:
/*
Definition for a binary tree node.
class TreeNode {
    int val;
    TreeNode left;
    TreeNode right;
    TreeNode() {}
    TreeNode(int val) { this.val = val; }
    TreeNode(int val, TreeNode left, TreeNode right) { this.val = val; this.left = left; this.right = right; }
}
*/
class Solution {
    private record Pair(boolean isBalanced, int h) {
        static Pair EMPTY = new Pair(true, 0);
    };

    public boolean isBalanced(TreeNode root) {
        return helper(root).isBalanced;
    }

    private Pair helper(TreeNode root) {
        if (root == null) {
            return Pair.EMPTY;
        }
        Pair left = helper(root.left);
        Pair right = helper(root.right);
        boolean isBalanced = left.isBalanced &&
                right.isBalanced &&
                (Math.abs(left.h - right.h) <= 1);
        int h = 1 + Math.max(left.h, right.h);
        return new Pair(isBalanced, h);
    }
}

