house-robber-iii.code:
/*
Definition for a binary tree node.
class TreeNode {
    int val;
    TreeNode left;
    TreeNode right;
    TreeNode() {}
    TreeNode(int val) { this.val = val; }
    TreeNode(int val, TreeNode left, TreeNode right) { this.val = val; this.left = left; this.right = right; }
}
*/
import java.util.*;

class Solution {
    private record Pair(int max, int childMax) {
    }

    public int rob(TreeNode root) {
        if (root == null)
            return 0;
        Map<TreeNode, Pair> map = new HashMap<>();
        var pair = rob(root, map);
        return pair.max;
    }

    private Pair rob(TreeNode root, Map<TreeNode, Pair> map) {
        if (root == null) {
            return new Pair(0, 0);
        }
        if (map.containsKey(root)) {
            return map.get(root);
        }
        var leftPair = rob(root.left, map);
        var rightPair = rob(root.right, map);

        int childMax = leftPair.max + rightPair.max;
        int max = Math.max(childMax, root.val + leftPair.childMax + rightPair.childMax);
        map.put(root, new Pair(max, childMax));
        return map.get(root);
    }
}

/*
Definition for a binary tree node.
class TreeNode {
    int val;
    TreeNode left;
    TreeNode right;
    TreeNode() {}
    TreeNode(int val) { this.val = val; }
    TreeNode(int val, TreeNode left, TreeNode right) { this.val = val; this.left = left; this.right = right; }
}
*/

class Solution {
    private record Pair(int max, int childMax) {
        static final Pair EMPTY = new Pair(0, 0);
    }

    public int rob(TreeNode root) {
        var pair = robHelper(root);
        return pair.max;
    }

    private Pair robHelper(TreeNode root) {
        if (root == null) {
            return Pair.EMPTY;
        }
        var leftPair = robHelper(root.left);
        var rightPair = robHelper(root.right);

        int childMax = leftPair.max + rightPair.max;
        int max = Math.max(childMax, root.val + leftPair.childMax + rightPair.childMax);
        return new Pair(max, childMax);
    }
}

max-area-of-island.code:
class Solution {
    public int maxAreaOfIsland(int[][] grid) {
        int m = grid.length;
        int n = grid[0].length;
        int maxArea = 0;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1) {
                    maxArea = Math.max(maxArea, area(grid, i, j, m, n));
                }
            }
        }
        return maxArea;
    }

    private int area(int[][] grid, int i, int j, int m, int n) {
        if (i < 0 || j < 0 || i >= m || j >= n || grid[i][j] != 1) {
            return 0;
        }
        grid[i][j] = 2;
        return 1 + area(grid, i + 1, j, m, n) + area(grid, i - 1, j, m, n) + area(grid, i, j + 1, m, n)
                + area(grid, i, j - 1, m, n);
    }
}

