class Solution {
    public int findTargetSumWays(int[] nums, int target) {
        int n = nums.length;
        int sum = 0;
        for (int num : nums) {
            sum += num;
        }
        if (target > sum || target < -sum) {
            return 0;
        }
        int[][] dp = new int[n + 1][2 * sum + 1];
        dp[0][sum] = 1;
        int reach = 0;
        for (int i = 1; i <= n; i++) {
            int offset = nums[i - 1];
            for (int j = -reach; j <= reach; j++) {
                dp[i][j + sum + offset] += dp[i - 1][j + sum];
                dp[i][j + sum - offset] += dp[i - 1][j + sum];
            }
            reach += offset;
        }
        return dp[n][target + sum];
    }
}

edit-distance.code:
class Solution {
    public int minDistance(String word1, String word2) {
        int m = word1.length();
        int n = word2.length();
        int[][] dp = new int[m + 1][n + 1];
        for (int i = 1; i <= n; i++) {
            dp[0][i] = i;
        }
        for (int i = 1; i <= m; i++) {
            dp[i][0] = i;
        }
        for (int i = 1; i <= m; i++) {
            char ch1 = word1.charAt(i - 1);
            for (int j = 1; j <= n; j++) {
                char ch2 = word2.charAt(j - 1);
                if (ch1 == ch2) {
                    dp[i][j] = dp[i - 1][j - 1];
                } else {
                    dp[i][j] = 1 + Math.min(dp[i - 1][j], Math.min(dp[i - 1][j - 1], dp[i][j - 1]));
                }
            }
        }
        return dp[m][n];
    }
}

class Solution {
    public int minDistance(String word1, String word2) {
        int m = word1.length();
        int n = word2.length();
        int[] pre = new int[n + 1];
        int[] curr = new int[n + 1];
        for (int i = 1; i <= n; i++) {
            pre[i] = i;
        }
        for (int i = 1; i <= m; i++) {
            char ch1 = word1.charAt(i - 1);
            curr[0] = i;
            for (int j = 1; j <= n; j++) {
                char ch2 = word2.charAt(j - 1);
                if (ch1 == ch2) {
                    curr[j] = pre[j - 1];
                } else {
                    curr[j] = 1 + Math.min(pre[j], Math.min(pre[j - 1], curr[j - 1]));
                }
            }
            int[] temp = pre;
            pre = curr;
            curr = temp;
        }

        // Don't forget the last swap
        return pre[n];
    }
}

class Solution {
    public int minDistance(String word1, String word2) {
        int m = word1.length();
        int n = word2.length();
        int[] dp = new int[n + 1];
        for (int i = 1; i <= n; i++) {
            dp[i] = i;
        }
        for (int i = 1; i <= m; i++) {
            char ch1 = word1.charAt(i - 1);
            int pre = dp[0];
            dp[0] = i;
            for (int j = 1; j <= n; j++) {
                char ch2 = word2.charAt(j - 1);
                int temp = dp[j];
                if (ch1 == ch2) {
                    dp[j] = pre;
                } else {
                    dp[j] = 1 + Math.min(dp[j], Math.min(pre, dp[j - 1]));
                }
                pre = temp;
            }
        }

        return dp[n];
    }
}

