import java.util.*;

class Solution {
    public boolean isInterleave(String s1, String s2, String s3) {
        int m = s1.length(), n = s2.length(), p = s3.length();
        if (p != m + n) {
            return false;
        }
        boolean[][] dp = new boolean[m + 1][n + 1];
        dp[0][0] = true;
        for (int i = 1; i <= n; i++) {
            dp[0][i] = s2.charAt(i - 1) == s3.charAt(i - 1) && dp[0][i - 1];
        }
        for (int i = 1; i <= m; i++) {
            dp[i][0] = s1.charAt(i - 1) == s3.charAt(i - 1) && dp[i - 1][0];
        }
        for (int i = 1; i <= m; i++) {
            for (int j = 1; j <= n; j++) {
                int k = i + j;
                dp[i][j] = (s1.charAt(i - 1) == s3.charAt(k - 1) && dp[i - 1][j])
                        || (s2.charAt(j - 1) == s3.charAt(k - 1) && dp[i][j - 1]);
            }
        }
        return dp[m][n];
    }
}

import java.util.*;

class Solution {
    public boolean isInterleave(String s1, String s2, String s3) {
        int m = s1.length(), n = s2.length(), p = s3.length();
        if (p != m + n) {
            return false;
        }
        boolean[] dp = new boolean[n + 1];
        dp[0] = true;
        for (int j = 1; j <= n; j++) {
            dp[j] = dp[j - 1] && s2.charAt(j - 1) == s3.charAt(j - 1);
        }
        for (int i = 1; i <= m; i++) {
            for (int j = 0; j <= n; j++) {
                int k = i + j;
                dp[j] = (s1.charAt(i - 1) == s3.charAt(k - 1) && dp[j])
                        || (j > 0 && s2.charAt(j - 1) == s3.charAt(k - 1) && dp[j - 1]);
            }
        }
        return dp[n];
    }
}

