class Solution {
    public boolean checkInclusion(String s1, String s2) {
        if (s2.length() < s1.length()) {
            return false;
        }
        int[] orig = new int[26];
        for (char ch : s1.toCharArray()) {
            orig[ch - 'a']++;
        }
        int[] copy = new int[26];
        int i = 0, j = 0;
        while (j < s2.length()) {
            int index = s2.charAt(j) - 'a';
            copy[index]++;
            while (copy[index] > orig[index]) {
                int left = s2.charAt(i) - 'a';
                copy[left]--;
                i++;
            }
            if (j - i + 1 == s1.length()) {
                return true;
            }
            j++;
        }
        return false;
    }
}

longest-repeating-character-replacement.code:
class Solution {
    public int characterReplacement(String s, int k) {
        int[] map = new int[26];
        int i = 0, j = 0;
        int maxLen = 0, freq = 0;
        while (j < s.length()) {
            int index = s.charAt(j) - 'A';
            map[index]++;
            if (map[index] > freq) {
                freq = map[index];
            }
            while (j - i + 1 - freq > k) {
                map[s.charAt(i) - 'A']--;
                freq = getFreq(map);
                i++;
            }
            if (j - i + 1 > maxLen) {
                maxLen = j - i + 1;
            }
            j++;
        }
        return maxLen;
    }

    private int getFreq(int[] arr) {
        int freq = 0;
        for (int e : arr) {
            if (e > freq) {
                freq = e;
            }
        }
        return freq;
    }
}

multiply-strings.code:
class Solution {
    public String multiply(String num1, String num2) {
        if (num1.equals("0") || num2.equals("0")) {
            return "0";
        }
        int m = num1.length(), n = num2.length();
        StringBuilder result = new StringBuilder();
        for (int i = m - 1, r = 0; i >= 0; i--, r++) {
            int n1 = num1.charAt(i) - '0';
            int currentCarry = 0, existingDigit = 0;
            int k = r;
            for (int j = n - 1; j >= 0; j--, k++) {
                int n2 = num2.charAt(j) - '0';
                existingDigit = k >= result.length() ? 0 : result.charAt(k) - '0';
                int val = n1 * n2 + existingDigit + currentCarry;
                currentCarry = val / 10;
                char digit = (char) (val % 10 + '0');
                if (k < result.length()) {
                    result.setCharAt(k, digit);
                } else {
                    result.append(digit);
                }
            }
            if (currentCarry != 0) {
                result.append((char) (currentCarry % 10 + '0'));
            }
        }
        return result.reverse().toString();
    }
}

