class Solution {
    public int longestCommonSubsequence(String text1, String text2) {
        int m = text1.length();
        int n = text2.length();
        int[][] dp = new int[m + 1][n + 1];
        for (int i = 1; i <= m; i++) {
            char ch1 = text1.charAt(i - 1);
            for (int j = 1; j <= n; j++) {
                char ch2 = text2.charAt(j - 1);
                if (ch1 == ch2) {
                    dp[i][j] = 1 + dp[i - 1][j - 1];
                } else {
                    dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]);
                }
            }
        }
        return dp[m][n];
    }
}

network-delay-time.code:
import java.util.*;

class Solution {
    public int networkDelayTime(int[][] times, int n, int k) {
        k = k - 1;
        List<List<int[]>> adj = new ArrayList<>(n);
        for (int i = 0; i < n; i++) {
            adj.add(new ArrayList<>());
        }
        for (int[] time : times) {
            int u = time[0] - 1;
            int v = time[1] - 1;
            int w = time[2];
            adj.get(u).add(new int[] { v, w });
        }
        int[] dist = new int[n];
        Arrays.fill(dist, Integer.MAX_VALUE);
        dist[k] = 0;
        Queue<int[]> minHeap = new PriorityQueue<>((a, b) -> a[1] - b[1]);
        minHeap.offer(new int[] { k, 0 });
        while (!minHeap.isEmpty()) {
            int[] pair = minHeap.poll();
            int node = pair[0];
            int distanceFromK = pair[1];
            if (dist[node] < distanceFromK) {
                continue;
            }
            for (int[] neiPair : adj.get(node)) {
                int nei = neiPair[0];
                int wt = neiPair[1];
                if (dist[node] + wt < dist[nei]) {
                    dist[nei] = dist[node] + wt;
                    minHeap.offer(new int[] { nei, dist[nei] });
                }
            }
        }

        int max = dist[0];
        for (int i = 1; i < n; i++) {
            if (dist[i] > max) {
                max = dist[i];
            }
        }
        return max == Integer.MAX_VALUE ? -1 : max;
    }
}

graph-valid-tree.code:
import java.util.*;

class Solution {
    private class DisjointSet {
        int n;
        int[] size;
        int[] parent;

        public DisjointSet(int n) {
            this.n = n;
            size = new int[n + 1];
            Arrays.fill(size, 1);
            parent = new int[n + 1];
            for (int i = 0; i <= n; i++) {
                parent[i] = i;
            }
        }

        public int getUltimateParent(int node) {
            if (parent[node] == node) {
                return node;
            }
            return parent[node] = getUltimateParent(parent[node]);
        }

        public boolean isConnected(int n1, int n2) {
            return getUltimateParent(n1) == getUltimateParent(n2);
        }

        public void unionBySize(int n1, int n2) {
            if (isConnected(n1, n2)) {
                return;
            }
            var u1 = getUltimateParent(n1);
            var u2 = getUltimateParent(n2);
            if (size[u1] > size[u2]) {
                size[u1] += size[u2];
                parent[u2] = u1;
            } else {
                size[u2] += size[u1];
                parent[u1] = u2;
            }
            n--;
        }
    }

    public boolean validTree(int n, int[][] edges) {
        if (edges.length + 1 != n) {
            return false;
        }
        DisjointSet ds = new DisjointSet(n);
        for (int[] edge : edges) {
            if (ds.isConnected(edge[0], edge[1])) {
                return false;
            }
            ds.unionBySize(edge[0], edge[1]);
        }
        return ds.n == 1;
    }
}

subsets-ii.code:
import java.util.*;

class Solution {
    List<Integer> current;
    List<int[]> all;

    public int[][] subsetsWithDup(int[] nums) {
        current = new LinkedList<>();
        all = new ArrayList<>();
        Arrays.sort(nums);
        backtrack(nums, 0);
        return all.toArray(new int[0][]);
    }

    private void backtrack(int[] nums, int index) {
        if (index == nums.length) {
            all.add(current.stream().mapToInt(Integer::intValue).toArray());
            return;
        }
        current.add(nums[index]);
        backtrack(nums, index + 1);
        current.remove(current.size() - 1);
        while (index + 1 < nums.length && nums[index] == nums[index + 1]) {
            index++;
        }
        backtrack(nums, index + 1);
    }
}

