import java.util.*;

class Solution {
    private class ListNode {
        ListNode prev;
        ListNode next;
        int key;
        int val;

        public ListNode(int key, int val) {
            this.key = key;
            this.val = val;
            this.prev = null;
            this.next = null;
        }
    };

    private class LRUCache {
        int capacity;
        ListNode head;
        ListNode tail;
        Map<Integer, ListNode> map;

        public LRUCache(int capacity) {
            this.capacity = capacity;
            map = new HashMap<>(capacity);
            head = new ListNode(0, 0);
            tail = new ListNode(0, 0);
            head.next = tail;
            tail.prev = head;
        }

        public int get(int key) {
            if (!map.containsKey(key)) {
                return -1;
            }
            var node = map.get(key);
            unlink(node);
            moveToEnd(node);
            return node.val;
        }

        public void put(int key, int val) {
            if (map.containsKey(key)) {
                get(key);
                var node = map.get(key);
                node.val = val;
            } else {
                var node = new ListNode(key, val);
                map.put(key, node);
                moveToEnd(node);
            }
            if (map.size() > capacity) {
                map.remove(head.next.key);
                unlink(head.next);
            }
        }

        private void unlink(ListNode node) {
            node.prev.next = node.next;
            node.next.prev = node.prev;
        }

        private void moveToEnd(ListNode node) {
            node.next = tail;
            node.prev = tail.prev;
            tail.prev.next = node;
            tail.prev = node;
        }
    };

    public int[] runLruCache(String[] operations, int[][] args) {
        var cache = new LRUCache(args[0][0]);
        var result = new ArrayList<Integer>();
        for (int i = 1; i < args.length; i++) {
            int key = args[i][0];
            String op = operations[i];
            if (op.equals("get")) {
                result.add(cache.get(key));
            } else {
                int val = args[i][1];
                cache.put(key, val);
            }
        }
        return result.stream().mapToInt(Integer::intValue).toArray();
    }
}

search-a-2d-matrix.code:
class Solution {
    public boolean searchMatrix(int[][] matrix, int target) {
        int m = matrix.length;
        int n = matrix[0].length;
        int low = 0, high = m * n - 1;
        while (low <= high) {
            int mid = low + (high - low) / 2;
            int row = mid / n;
            int col = mid % n;
            int midVal = matrix[row][col];
            if (midVal == target) {
                return true;
            }
            if (midVal > target) {
                high = mid - 1;
            } else {
                low = mid + 1;
            }
        }
        return false;
    }
}

search-in-rotated-sorted-array.code:
class Solution {
    public int search(int[] nums, int target) {
        int low = 0, high = nums.length - 1;
        while (low <= high) {
            int mid = low + (high - low) / 2;
            if (nums[mid] == target) {
                return mid;
            }
            // 2,3,4,5,1
            if (nums[low] <= nums[mid]) {
                if (target >= nums[low] && target < nums[mid]) {
                    high = mid - 1;
                } else {
                    low = mid + 1;
                }
            } else {
                if (target > nums[mid] && target <= nums[high]) {
                    low = mid + 1;
                } else {
                    high = mid - 1;
                }
            }
        }
        return -1;
    }
}

longest-substring-without-repeating-char.code:
import java.util.*;

class Solution {
    public int lengthOfLongestSubstring(String s) {
        int maxLen = 0;
        int i = 0, j = 0;
        Set<Character> set = new HashSet<Character>();
        while (j < s.length()) {
            char c = s.charAt(j);
            while (set.contains(c)) {
                set.remove(s.charAt(i));
                i++;
            }
            set.add(c);
            maxLen = Math.max(maxLen, j - i + 1);
            j++;
        }
        return maxLen;

    }
}

best-time-to-buy-and-sell-stock.code:
class Solution {
    public int maxProfit(int[] prices) {
        int profMax = 0;
        int priceMin = prices[0];
        for (int i = 1; i < prices.length; i++) {
            if (prices[i] < priceMin) {
                priceMin = prices[i];
            } else if (prices[i] - priceMin > profMax) {
                profMax = prices[i] - priceMin;
            }
        }
        return profMax;
    }
}

evaluate-reverse-polish-notation.code:
import java.util.*;

class Solution {
    public int evalRpn(String[] tokens) {
        Deque<Integer> stack = new ArrayDeque<>();
        for (String token : tokens) {
            if (Character.isDigit(token.charAt(0))
                    || (token.charAt(0) == '-' && token.length() > 1)) {
                int val = Integer.parseInt(token);
                stack.push(val);
                continue;
            }
            int op2 = stack.pop();
            int op1 = stack.pop();
            switch (token) {
                case "+":
                    stack.push(op1 + op2);
                    break;
                case "-":
                    stack.push(op1 - op2);
                    break;
                case "*":
                    stack.push(op1 * op2);
                    break;
                case "/":
                    stack.push(op1 / op2);
                    break;
                default:
            }
        }
        return stack.pop();
    }
}

min-stack.code:
import java.util.*;

class Solution {
    public int[] runMinStack(String[] operations, int[] values) {
        Deque<Integer> stack = new ArrayDeque<>();
        Deque<Integer> minStack = new ArrayDeque<>();
        List<Integer> result = new ArrayList<>();
        for (int i = 0; i < operations.length; i++) {
            String op = operations[i];
            int val = values[i];
            if (op.equals("push")) {
                stack.push(val);
                if (minStack.isEmpty() || minStack.peek() > val) {
                    minStack.push(val);
                } else {
                    minStack.push(minStack.peek());
                }
            } else if (op.equals("pop")) {
                stack.pop();
                minStack.pop();
            } else if (op.equals("top")) {
                result.add(stack.peek());
            } else {
                result.add(minStack.peek());
            }
        }
        return result.stream().mapToInt(Integer::intValue).toArray();
    }
}

two-sum-ii-input-array-is-sorted.code:
class Solution {
    public int[] twoSum(int[] numbers, int target) {
        int i = 0, j = numbers.length - 1;
        while (i < j) {
            int sum = numbers[i] + numbers[j];
            if (sum < target) {
                i++;
            } else if (sum > target) {
                j--;
            } else {
                return new int[] { i + 1, j + 1 };
            }
        }
        return new int[0];
    }
}

3sum.code:
import java.util.*;

class Solution {
    public int[][] threeSum(int[] nums) {
        int n = nums.length;
        List<int[]> result = new ArrayList<>();
        Arrays.sort(nums);
        for (int i = 0; i < n - 2; i++) {
            int j = i + 1;
            int k = n - 1;
            while (j < k) {
                int target = -nums[i];
                int sum = nums[j] + nums[k];
                if (sum < target) {
                    j++;
                } else if (sum > target) {
                    k--;
                } else {
                    result.add(new int[] { nums[i], nums[j], nums[k] });
                    while (k > i + 1 && nums[k] == nums[k - 1]) {
                        k--;
                    }
                    while (j < n - 1 && nums[j] == nums[j + 1]) {
                        j++;
                    }
                    j++;
                    k--;
                }
            }
            while (i < n - 2 && nums[i] == nums[i + 1]) {
                i++;
            }
        }
        return result.toArray(new int[0][]);
    }
}

